const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={data:null,tab:new URLSearchParams(location.search).get('tab')||'overview',query:'',filter:'',department:'',roleId:new URLSearchParams(location.search).get('roleId')||'',entityId:new URLSearchParams(location.search).get('entityId')||'',employeeId:new URLSearchParams(location.search).get('employeeId')||'',form:null};
const DOC_KINDS=['Job Description','Terms of Reference','Role Description','Appointment Responsibilities','Committee TOR','Project Scope','Delegation of Authority','Functional Responsibilities'];
const DOC_FIELDS=['Purpose','Responsibilities','Accountabilities','Authority','Internal relationships','External relationships','Performance expectations','KPIs','Academic qualifications','Professional qualifications','Experience','Competencies','Technical skills','Behavioural skills','Other requirements','Working conditions'];
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kuala_Lumpur',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const notify=msg=>$('#position-status').textContent=msg;
const pill=(v)=>`<span class="pill ${['Active','Acknowledged','Current','Verified','Published'].includes(v)?'good':['Overdue','Expired','Assignment Ended'].includes(v)?'danger':['Pending','Draft','Reacknowledgement Required','Pending Verification'].includes(v)?'warning':''}">${esc(v)}</span>`;
const empty=msg=>`<div class="empty">${esc(msg)}</div>`;
const options=(items,selected='',blank='Choose…')=>(blank===null?'':`<option value="">${esc(blank)}</option>`)+items.map(item=>{const v=Array.isArray(item)?item[0]:item,label=Array.isArray(item)?item[1]:item;return `<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(label)}</option>`}).join('');
const table=(head,rows)=>rows.length?`<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty('No matching records.');
async function api(path,options={}){const r=await fetch('/api/positions'+path,options),d=await r.json();if(!r.ok)throw Error(d.error||'This request could not be completed.');return d;}
const post=(path,b)=>api(path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(b)});
const matches=v=>JSON.stringify(v).toLowerCase().includes(state.query.toLowerCase());
function visibleAssignments(){return state.data.assignments.filter(a=>(!state.employeeId||a.employee_id===state.employeeId)&&(!state.roleId||a.role_id===state.roleId)&&(!state.entityId||[a.data.entityId,a.role?.data.entityId,a.role?.data.committeeId,a.role?.data.projectId].includes(state.entityId))&&(!state.department||a.department===state.department)&&(!state.filter||[a.ackStatus,a.period,a.role?.type,a.visibility].includes(state.filter)||state.filter==='Expiring'&&a.period==='Current'&&a.effectiveEndDate&&Date.parse(a.effectiveEndDate)-Date.parse(today())<=60*86400000||state.filter==='Multiple roles'&&a.period==='Current'&&state.data.assignments.filter(x=>x.employee_id===a.employee_id&&x.period==='Current').length>1||state.filter==='Pending'&&a.period==='Current'&&a.ackStatus==='Reacknowledgement Required')&&matches([a.employeeName,a.employee_id,a.title,a.department,a.entityName]));}
const byDepartment=(a,b)=>(a.department||'').localeCompare(b.department||'')||(a.title||a.employee_name||'').localeCompare(b.title||b.employee_name||'');
const sharedRoles=()=>state.data.roles.filter(r=>!r.data.entityAssignment).sort(byDepartment);
function roles(){return sharedRoles().filter(r=>(!state.roleId||r.id===state.roleId)&&(!state.department||r.department===state.department)&&(!state.filter||[r.status,r.type].includes(state.filter)||state.filter==='Missing JD / TOR'&&r.status==='Active'&&r.data.acknowledgementRequired!==false&&!state.data.documents.some(d=>d.role_id===r.id&&d.viewStatus==='Current'))&&matches([r.title,r.data.displayTitle,r.code,r.department,r.data.division,r.data.reportsTo]));}
function toolbar(){
 const hr=state.data.access.hr,isLibrary=state.tab==='library',isAssignments=state.tab==='assignments',isDocs=state.tab==='documents',isQual=state.tab==='qualifications';
 $('#position-tools').innerHTML=state.tab==='settings'?'':`<label>Search<input id="position-search" type="search" placeholder="Employee, position, department, qualification…" value="${esc(state.query)}"></label>${isLibrary||isAssignments?`<label>Department<select id="department-filter">${options([...new Set((isAssignments?state.data.assignments.map(a=>a.department):sharedRoles().map(r=>r.department)))].sort(),state.department,'All departments')}</select></label><label>Filter<select id="record-filter">${options(isLibrary?['Draft','Active','Inactive','Archived','Missing JD / TOR',...state.data.types.map(t=>t.name)]:['Current','Upcoming','Historical','Pending','Overdue','Reacknowledgement Required','Acknowledged','Expiring','Multiple roles','Public','Internal','Restricted'],state.filter,'All records')}</select></label>`:isQual?`<label>Verification<select id="record-filter">${options(['Verified','To verify','Pending Verification','Employee Declared','Expired','Rejected','Not Applicable'],state.filter,'All records')}</select></label>`:''}${isDocs?`<label>Position / role<select id="document-role-filter">${options(sharedRoles().map(r=>[r.id,r.department+' · '+(r.data.displayTitle||r.title)]),state.roleId,'All positions')}</select></label><label>Document status<select id="record-filter">${options(['Current','Draft','Upcoming','Due for review','History'],state.filter,'Latest versions')}</select></label>`:''}${hr&&isAssignments?`<label>Employee<select id="employee-filter">${options(state.data.employees.map(e=>[e.employee_id,e.employee_name+' · '+e.employee_id]),state.employeeId,'All employees')}</select></label>`:''}${(state.roleId||state.entityId||state.employeeId||state.department||state.filter||state.query)?'<button data-action="clear-filters">Clear filters</button>':''}${hr&&isLibrary?'<button class="primary" data-action="new-role">＋ New position / role</button>':hr&&isAssignments?'<button class="primary" data-action="assign">＋ Assign role</button>':hr&&isDocs?'<button class="primary" data-action="new-document">＋ New document version</button>':hr&&state.tab==='entities'?'<button class="primary" data-action="new-entity">＋ Committee / project</button>':''}`;
 $('#position-search')?.addEventListener('input',e=>{state.query=e.target.value;content()});
 $('#department-filter')?.addEventListener('change',e=>{state.department=e.target.value;content()});
 $('#record-filter')?.addEventListener('change',e=>{state.filter=e.target.value;content()});
 $('#document-role-filter')?.addEventListener('change',e=>{state.roleId=e.target.value;content()});
 $('#employee-filter')?.addEventListener('change',e=>{state.employeeId=e.target.value;content()});
}
const labels={activePositions:'Active positions',activeAssignments:'Current appointments',multipleRoles:'Employees with multiple roles',positionsWithoutJd:'Active roles needing JD / TOR',documentsDueReview:'Documents due for review',pendingAcknowledgements:'Pending acknowledgements',overdueAcknowledgements:'Overdue acknowledgements',expiringAppointments:'Appointments ending within 60 days',committeeExpiry:'Committee roles ending within 60 days',actingExpiry:'Acting / interim roles ending within 60 days',qualificationsPending:'Qualifications to verify',publishedProfiles:'Public directory profiles'};
function overview(){
 const d=state.data;if(!d.access.hr)return assignments()+notifications();
 const keyStats=['activePositions','activeAssignments','positionsWithoutJd','pendingAcknowledgements','overdueAcknowledgements','expiringAppointments','documentsDueReview','qualificationsPending'];
 return `<div class="stat-grid">${keyStats.map(k=>`<button class="stat-tile" data-stat="${k}"><span>${esc(labels[k])}</span><strong>${d.stats[k]||0}</strong></button>`).join('')}</div><section class="panel ownership-guide"><h2>Maintain each record once</h2><div class="ownership-grid"><button data-tab="library"><strong>Position library</strong><span>Shared titles, departments, reporting positions and eligibility</span></button><button data-tab="assignments"><strong>Appointments</strong><span>Employee, primary job, dates, visibility and acknowledgement</span></button><button data-tab="documents"><strong>JD / TOR versions</strong><span>One controlled responsibilities document per role and version</span></button><button data-tab="entities"><strong>Committees & projects</strong><span>Institutional details and the same linked employee appointments</span></button></div><p class="note">An effective primary appointment updates the Employee Master, profile, directory, organisation chart, workforce views and work details used by other modules. Business cards use approved public appointments. The Google Sheet receives these shared registers on its next successful automatic sync.</p></section><div class="section-heading"><h2>Next actions</h2><button data-tab="assignments">View appointments →</button></div>${table(['Employee','Position / appointment','Action'],d.assignments.filter(a=>a.period==='Current'&&['Pending','Overdue','Reacknowledgement Required','Document Required'].includes(a.ackStatus)).slice(0,8).map(a=>[esc(a.employeeName)+`<small>${esc(a.employee_id)}</small>`,esc(a.title),pill(a.ackStatus)]))}<details class="panel source-library"><summary>Source libraries · ${d.sourceImported} of ${d.sourceCount} imported positions</summary><p class="note">Imported source responsibilities remain drafts until reviewed and published. They do not change employee appointments automatically.</p><button data-action="import" ${d.sourceImported===d.sourceCount?'disabled':''}>Import source drafts</button></details>${notifications()}`;
}
function library(){
 const hr=state.data.access.hr,rows=roles();return `<p class="note">${rows.length} shared ${rows.length===1?'position / role':'positions & roles'} · Shared responsibilities are maintained once and linked to employee appointments.</p><div class="library-grid">${rows.map(r=>{const docs=state.data.documents.filter(d=>d.role_id===r.id),assignments=state.data.assignments.filter(a=>a.role_id===r.id&&a.period==='Current');return `<article class="role-card"><div class="role-code">${esc(r.code)}</div><h2>${esc(r.data.displayTitle||r.title)}</h2><div class="pills">${pill(r.status)}${pill(r.type)}</div><p>${esc(r.department)}${r.data.division&&r.data.division.trim().toLowerCase()!==r.department.trim().toLowerCase()?' · '+esc(r.data.division):''}</p><p>Reporting position: ${esc(state.data.roles.find(x=>x.id===r.data.reportingPositionId)?.title||'Not set')}</p><small>${assignments.length} current appointments · ${docs.length} document ${docs.length===1?'version':'versions'}</small><div class="card-actions"><button data-role-docs="${r.id}">Responsibilities</button>${hr?`<button data-edit-role="${r.id}">Edit role</button><button data-assign-role="${r.id}" ${r.status!=='Active'?'disabled':''}>Assign</button>`:''}</div></article>`}).join('')}</div>${!rows.length?empty('No matching roles. Import the source library or create a new position.'):''}`;
}
function appointment(a){
 const hr=state.data.access.hr,own=a.employee_id===state.data.access.employeeId;
 return `<article class="appointment-card ${a.is_primary?'primary-role':''}"><div><p class="role-code">${esc(a.employeeName)} · ${esc(a.employee_id)}</p><h2>${esc(a.title||'Role unavailable')}</h2><div class="pills">${pill(a.is_primary?'Primary position':a.role?.type)}${pill(a.period)}${pill(a.ackStatus)}</div><p>${esc(a.department)} · ${esc(a.effectiveStartDate)} → ${esc(a.effectiveEndDate||'Ongoing')}</p><p>${esc(a.visibility)} · Business card: ${a.publish_card?'Published when eligible':'Not selected'}${a.data.renewable?' · Renewable':''}</p>${a.data.entityId?`<p>${esc(a.entityName||'Linked institutional entity')}</p>`:''}<div class="card-actions">${hr?`<button data-publication="${a.id}">Visibility</button>${a.status==='Assigned'?`<button data-extend="${a.id}">Extend</button><button data-end="${a.id}" ${a.start_date>today()?'disabled':''}>End appointment</button>`:''}${a.end_date?`<button data-renew="${a.id}">Renew / replace</button>`:''}<a class="button" href="/admin/profiles?employeeId=${encodeURIComponent(a.employee_id)}">Profile →</a>`:own?`<button data-correction="${a.id}">Request correction</button>`:''}</div></div><div>${a.documents.length?a.documents.map(d=>`<div class="document-row"><div><strong>${esc(d.kind)}</strong><small>Version ${d.version} · ${d.acknowledgedAt?'Acknowledged '+new Date(d.acknowledgedAt).toLocaleString('en-MY'):d.status==='Not Required'?'Acknowledgement not required':'Due '+d.dueDate}</small>${pill(d.status)}</div><button data-read-doc="${d.id}" data-assignment="${a.id}">${own&&['Pending','Overdue','Reacknowledgement Required'].includes(d.status)?'Read & acknowledge':'Read'}</button></div>`).join(''):empty(a.ackStatus==='Not Required'?'Document acknowledgement is not required for this appointment.':a.period==='Historical'?'Historical appointment · current responsibilities are not required.':'No applicable published responsibilities document.')}<details class="history"><summary>Document & acknowledgement history</summary>${(a.ackHistory||[]).map(h=>`<p class="note">${esc(h.kind)} v${h.version} · ${esc(h.status)} · acknowledged ${new Date(h.acknowledgedAt).toLocaleString("en-MY")}</p>`).join("")}${state.data.documents.filter(d=>d.role_id===a.role_id&&d.status==='Published'&&!a.documents.some(x=>x.id===d.id)).map(d=>`<div class="document-row"><div>${esc(d.kind)} · v${d.version}<small>Superseded / historical version</small></div><button data-read-doc="${d.id}" data-assignment="${a.id}">Read</button></div>`).join('')||'<p class="note">No previous published versions.</p>'}</details></div></article>`;
}
function assignments(){const rows=visibleAssignments(),current=rows.filter(a=>a.period!=='Historical'),history=rows.filter(a=>a.period==='Historical');return `<p class="note">${rows.length} appointments · Current and upcoming appointments are shown first. Historical records are retained.</p>${current.map(appointment).join('')||empty('No current appointments in this view.')}${history.length?`<details class="history" ${state.filter==='Historical'?'open':''}><summary>Past appointments · ${history.length}</summary>${history.map(appointment).join('')}</details>`:''}`}
function documents(){
 let rows=state.data.documents.filter(d=>(!state.roleId||d.role_id===state.roleId)&&matches([d.title,d.kind,d.version,state.data.roles.find(r=>r.id===d.role_id)?.code]));
 if(state.filter==='Due for review')rows=rows.filter(d=>d.viewStatus==='Current'&&d.review_date&&d.review_date<=today());
 else if(state.filter==='History')rows=rows.filter(d=>['Superseded','Expired'].includes(d.viewStatus));
 else if(state.filter)rows=rows.filter(d=>d.viewStatus===state.filter);
 const latestDraft=new Map();for(const d of rows.filter(d=>d.status==='Draft')){const key=d.role_id+':'+d.kind;if(!latestDraft.has(key)||latestDraft.get(key).version<d.version)latestDraft.set(key,d);}
 const main=rows.filter(d=>['Current','Upcoming'].includes(d.viewStatus)||d.status==='Draft'&&latestDraft.get(d.role_id+':'+d.kind)?.id===d.id),history=rows.filter(d=>!main.includes(d));
 const grid=list=>table(['Position / document','Version','Status','Dates','Actions'],list.map(d=>[esc(d.title)+`<small>${esc(state.data.roles.find(r=>r.id===d.role_id)?.data.displayTitle||state.data.roles.find(r=>r.id===d.role_id)?.title)} · ${esc(d.kind)}</small>`,esc(d.version),pill(d.viewStatus||d.status),`Effective: ${esc(d.effective_date||'Not set')}<small>Review: ${esc(d.review_date||'—')} · Expiry: ${esc(d.expiry_date||'—')}</small>`,`<div class="doc-links"><button data-read-doc="${d.id}">Read</button>${state.data.access.hr?`<button data-new-version="${d.id}">Revise</button>${d.status==='Draft'?`<button data-publish-doc="${d.id}">Review & publish</button>`:''}`:''}</div>`]));
 return `<section class="panel"><h2>Responsibilities · current & draft versions</h2><p class="note">One current published version per document type. The latest drafts appear here; earlier versions and employee receipts remain in history. Publishing responsibilities does not create a second employee record.</p>${main.length?grid(main):state.filter==='History'?'':empty('No current or latest draft documents in this view.')}${history.length?`<details class="history" ${state.filter==='History'?'open':''}><summary>Previous & expired versions · ${history.length}</summary>${grid(history)}</details>`:''}</section>`;
}
function qualifications(){const rows=state.data.qualifications.filter(r=>(!state.filter||(r.verificationStatus||'Pending Verification')===state.filter||state.filter==='To verify'&&(!r.verificationStatus||['Pending Verification','Employee Declared'].includes(r.verificationStatus)))&&matches([r.employeeName,r.employeeId,r.qualification,r.field,r.body,r.institution]));return `<section class="panel"><h2>Qualification verification</h2><p class="note">Academic and professional qualifications use the existing employee profile records. Certificates, transcripts, membership numbers and personal identifiers are never included on public cards.</p>${table(['Employee','Qualification','Verification','Expiry / publication','Maintain'],rows.map(r=>[esc(r.employeeName)+`<small>${esc(r.employeeId)}</small>`,esc(r.qualification)+`<small>${esc(r.kind)} · ${esc(r.institution||r.body||'')}</small>`,pill(r.verificationStatus||'Pending Verification'),`${r.expiry&&r.expiry<today()?pill('Expired'):esc(r.expiry||'No expiry')}<small>${esc(r.visibility||'Internal')} · Card: ${esc(r.publishCard||'No')}</small>`,`<a class="button" href="/admin/profiles?employeeId=${encodeURIComponent(r.employeeId)}&section=qualifications">Review profile</a>`]))}</section>`}
function entities(){const rows=state.data.entities.filter(e=>(!state.entityId||e.id===state.entityId)&&matches(e));return `<p class="note">Maintain committee and project details here. Employee membership uses the same Appointments register and does not create a second primary job.</p><div class="library-grid">${rows.map(e=>{const members=state.data.assignments.filter(a=>[a.data.entityId,a.role?.data.entityId,a.role?.data.committeeId,a.role?.data.projectId].includes(e.id)),current=members.filter(a=>a.period==='Current');return `<article class="role-card"><span class="role-code">${esc(e.code)}</span><h2>${esc(e.name)}</h2><div class="pills">${pill(e.kind)}${pill(e.status)}</div><p>${esc(e.data.purpose)}</p><p>${esc(e.data.effectiveDate||'')} → ${esc(e.data.expiryDate||'Ongoing')}</p><p>Authority: ${esc(e.data.authority||'Not recorded')}</p><small>${current.length} current appointments · ${members.length-current.length} upcoming / past</small><div class="card-actions"><button data-entity-appointments="${e.id}">View appointments</button>${state.data.access.hr?`<button data-edit-entity="${e.id}">Edit details</button><button data-assign-entity="${e.id}" ${e.status!=='Active'?'disabled':''}>Assign employee</button>`:''}${e.data.torRoleId?`<button data-role-docs="${e.data.torRoleId}">Shared TOR</button>`:''}</div><details><summary>Current members</summary>${current.map(a=>`<p>${esc(a.employeeName)} · ${esc(a.role?.data.capacity||a.role?.type)}</p>`).join('')||'<p>No current members.</p>'}</details></article>`}).join('')}</div>${!rows.length?empty('No matching committees or projects.'):''}`;}
function notifications(){const rows=state.data.notifications.filter(n=>!state.employeeId||n.employee_id===state.employeeId).filter(n=>!n.read_at).slice(0,12);return rows.length?`<section class="panel"><h2>Appointment reminders</h2><div class="notifications">${rows.map(n=>`<div class="notification"><div>${esc(n.message)}<small>${esc(state.data.employees.find(e=>e.employee_id===n.employee_id)?.employee_name||n.employee_id)} · ${new Date(n.created_at).toLocaleDateString('en-MY')}</small></div>${n.employee_id===state.data.access.employeeId?`<button data-read-notification="${esc(n.id)}">Dismiss</button>`:''}</div>`).join('')}</div></section>`:'';}
function settings(){const s=state.data.settings;return `<section class="panel"><h2>Sync & ownership rules</h2><p>Position Library → primary appointment → Employee Master → connected modules and business cards. Qualifications are maintained in Employee Profile. Committees and projects maintain entity details; Appointments maintains their members. Google Sheet role registers are maintained by the Site.</p><p>Only active, effective and unexpired roles and entities are current. Primary roles maintain the employee’s main job; additional appointments stay separate. Previous reviews, issued letters, documents and receipts keep their history.</p><h3>Reminders & publication</h3><p>Responsibility acknowledgement: <strong>${s.acknowledgementDays} days</strong></p><p>Reminder days: ${s.reminderDays.join(', ')}</p><p>Appointment expiry alerts: ${s.expiryDays.join(', ')} days before expiry</p><p>Employee-declared qualifications on public cards: ${s.allowEmployeeDeclaredPublic?'Allowed by P&C policy':'Not permitted'}</p><button data-action="settings">Edit rules</button><p class="note">Persistent in-app reminders are evaluated when this module is opened and by the existing authorised Google Sheet sync runner. Email delivery is not configured.</p></section><section class="panel"><h2>Role types</h2><div class="pills">${state.data.types.map(t=>pill(t.name)).join('')}</div></section>`;}
function reports(){return `<section class="panel"><h2>Governance reports</h2><p class="note">Download records as CSV for Excel, or print the current view to PDF. Exports retain employee names and IDs.</p><div class="report-actions"><select id="report-type">${options(['Position listing','Employee appointments','Multiple-role employees','Document versions','Acknowledgement status','Pending / overdue','Appointment expiry','Qualification register','Public profile publication'],'Position listing',null)}</select><button data-action="export">Download CSV</button><button data-action="print">Print / save PDF</button></div></section><section class="panel" id="report-preview"></section>${table(['Report','Available records'],[['Position & role library',sharedRoles().length],['Employee appointments',state.data.assignments.length],['Document versions',state.data.documents.length],['Academic / professional qualifications',state.data.qualifications.length]].map(r=>r.map(esc)))}`;}
async function audit(){try{const d=await api('/audit');if(state.tab!=='audit')return;$('#position-content').innerHTML=`<section class="panel"><h2>Governance audit trail</h2>${table(['Time','Actor','Action','Record','Change'],d.audit.filter(matches).map(a=>[esc(new Date(a.created_at).toLocaleString('en-MY')),esc(a.actor_email),esc(a.action),esc(a.employee_id||a.entity_id),`<details><summary>Before / after</summary><pre>${esc(JSON.stringify({before:a.before_json?JSON.parse(a.before_json):null,after:a.after_json?JSON.parse(a.after_json):null},null,2))}</pre></details>`]))}</section>`}catch(e){notify(e.message)}}
function content(){const fn={overview,library,assignments,documents,qualifications,entities,settings,reports};$('#position-content').innerHTML=fn[state.tab]?.()||empty('Loading audit records…');if(state.tab==='audit')audit();if(state.tab==='reports'){const show=()=>{const type=$('#report-type').value,{headers,rows}=reportData(type);$('#report-preview').innerHTML='<h2>'+esc(type)+'</h2>'+table(headers,rows.map(r=>headers.map(h=>esc(r[h]))));};$('#report-type').onchange=show;show();}}
function render(){const hr=state.data.access.hr,tabs=hr?[['overview','Overview'],['library','Position library'],['assignments','Appointments'],['documents','JD / TOR versions'],['qualifications','Qualification requirements'],['entities','Committees & projects'],['reports','Reports'],['audit','Audit trail'],['settings','Rules']]:[['assignments','Positions & appointments'],['overview','Reminders']];if(!tabs.some(t=>t[0]===state.tab))state.tab='assignments';$('#page-heading').textContent=hr?'Position & role library':state.data.access.role==='employee'?'My positions & appointments':'Team positions & appointments';$('#page-intro').textContent=hr?'One library. Every appointment. Clear accountability.':'Your responsibilities, appointments and acknowledgement history in one place.';const tabButton=([key,label])=>`<button data-tab="${key}" class="${state.tab===key?'active':''}" ${state.tab===key?'aria-current="page"':''}>${label}</button>`;const menu=(label,keys)=>`<details class="position-menu" name="position-menu"><summary class="${keys.includes(state.tab)?'active':''}">${label}${keys.includes(state.tab)?' · '+tabs.find(t=>t[0]===state.tab)[1]:''}</summary><div>${keys.map(k=>tabButton(tabs.find(t=>t[0]===k))).join('')}</div></details>`;$('#position-tabs').innerHTML=hr?tabButton(tabs[0])+menu('Role library',['library','documents','qualifications'])+tabButton(tabs.find(t=>t[0]==='assignments'))+tabButton(tabs.find(t=>t[0]==='entities'))+menu('Reports & settings',['reports','audit','settings']):tabs.map(tabButton).join('');const params=new URLSearchParams(location.search);for(const k of ['tab','roleId','entityId','employeeId']){if(state[k])params.set(k,state[k]);else params.delete(k)}history.replaceState(null,'',location.pathname+'?'+params.toString());toolbar();content();}
async function refresh(msg=''){state.data=await api('');render();notify(msg);}
const input=(key,label,value='',type='text',wide=false)=>`<label class="${wide?'wide':''}">${esc(label)}<input name="${key}" type="${type}" value="${esc(value||'')}"></label>`;
const select=(key,label,values,value='',blank=null)=>`<label>${esc(label)}<select name="${key}">${options(values,value,blank)}</select></label>`;
const textarea=(key,label,value='',wide=true)=>`<label class="${wide?'wide':''}">${esc(label)}<textarea name="${key}">${esc(value)}</textarea></label>`;
const check=(key,label,value=false)=>`<label class="check-label"><input type="checkbox" name="${key}" ${value?'checked':''}>${esc(label)}</label>`;
